    "=r"(R[12]), "=r"(R[13]), "=r"(R[14]), "=r"(R[15]) : "r"(ADDR))
__global__ void __launch_bounds__(kThreads, 1) tc_pair2_kernel(const __grid_constant__ CUtensorMap mapW, const __grid_constant__ CUtensorMap mapE1,
    const __grid_constant__ CUtensorMap mapE2, const float* __restrict__ bias, OutPtrs outs, int B, int Bpad, int n1, int kbs, int stages, int mode,
    unsigned long long* prof) {
  const uint64_t t_start = clk(), g_start = gtime();
  extern __shared__ uint8_t smem_raw[];
  __shared__ __align__(8) uint64_t full[kMaxStages], empty[kMaxStages], accum;
  __shared__ uint32_t tmem_slot;
  const uint32_t sbase = (smem_u32(smem_raw) + 1023) & ~1023u;
  const int n2 = Bpad - n1, n2h = n2 / 2;
  const uint32_t e1Blk = (n1 / 2) * 128, eBlk = (Bpad / 2) * 128, stageBytes = kbs * (kWBlk + eBlk);
  const int nIt = kKB / kbs, wg = (mode & 512) ? 2 : (mode & 1024) ? 3 : 1;
  const int warp = threadIdx.x >> 5, lane = threadIdx.x & 31;
