  if (warp == 0 && lane == 0) {
    uint64_t pol; asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;" : "=l"(pol));
    for (int i = 0; i < nIt; ++i) {
      const int s = i % stages;
      if (i >= stages) mbar_wait(smem_u32(&empty[s]), ((i / stages) - 1) & 1);
      const uint32_t fl = smem_u32(&full[s]);
      if ((mode & 2) && i >= stages) { if (rank == 0) mbar_arrive(fl); continue; }
      const uint32_t fb = mapa0(fl);
      if (rank == 0) asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;" ::"r"(fl), "r"(2 * stageBytes) : "memory");
      const uint32_t a = sbase + s * stageBytes, b = a + kbs * kWBlk;
      asm volatile("cp.async.bulk.tensor.3d.cta_group::2.shared::cluster.global.mbarrier::complete_tx::bytes.L2::cache_hint [%0], [%1, {%3, %4, %5}], [%2], %6;"
          ::"r"(a), "l"((uint64_t)&mapW), "r"(fb), "r"(0), "r"(m0), "r"(i * kbs), "l"(pol) : "memory");
      for (int j = 0; j < kbs; ++j) {
        const int kc = (i * kbs + j) * kBK;
        asm volatile("cp.async.bulk.tensor.2d.cta_group::2.shared::cluster.global.mbarrier::complete_tx::bytes [%0], [%1, {%3, %4}], [%2];"
            ::"r"(b + j * eBlk), "l"((uint64_t)&mapE1), "r"(fb), "r"(kc), "r"((int)rank * (n1 / 2)) : "memory");
        asm volatile("cp.async.bulk.tensor.2d.cta_group::2.shared::cluster.global.mbarrier::complete_tx::bytes [%0], [%1, {%3, %4}], [%2];"
            ::"r"(b + j * eBlk + e1Blk), "l"((uint64_t)&mapE2), "r"(fb), "r"(kc), "r"(n1 + (int)rank * n2h) : "memory");
      }
    }
