    const uint32_t ib = (1u << 4) | (2u << 7) | (2u << 10) | ((uint32_t)(2 * kRows >> 4) << 24);
    const uint32_t idesc1 = ib | ((uint32_t)(n1 >> 3) << 17), idesc2 = ib | ((uint32_t)(n2 >> 3) << 17);
    for (int i = 0; i < nIt; ++i) {
      const int s = i % stages;
      if (i % wg == 0) {
        for (int g = 0; g < wg && i + g < nIt; ++g) mbar_wait(smem_u32(&full[(i + g) % stages]), ((i + g) / stages) & 1);
        if (i == 0) t_first = clk();
