            if (!(mode & 4)) mma2(tmem + n1, da + 2 * k, db2 + 2 * k, idesc2, acc);
          }
        }
      }
      umma_commit2(smem_u32(&empty[s]));
    }
    umma_commit2(smem_u32(&accum));
  }
  __syncwarp();
  mbar_wait(smem_u32(&accum), 0);
  asm volatile("tcgen05.fence::after_thread_sync;");
  const uint64_t t_acc = clk();
  const int q = warp & 3, h = warp >> 2;
  const int m = m0 + q * 32 + lane;
  const int c = m0 / kD;
  const float bv = bias[m];
  float* o = outs.p[c] + (m - c * kD);
  for (int c0 = h * 16; c0 < Bpad; c0 += 32) {
    uint32_t r[16]; LD16(r, tmem + ((uint32_t)(q * 32) << 16) + c0);
    asm volatile("tcgen05.wait::ld.sync.aligned;" ::: "memory");
#pragma unroll
    for (int i = 0; i < 16; ++i) if (c0 + i < B) o[(size_t)(c0 + i) * kD] = __uint_as_float(r[i]) + bv;
  }
  const uint64_t t_epi = clk();
  asm volatile("tcgen05.fence::before_thread_sync;");
  cluster_sync();
  if (prof) {
    if (threadIdx.x == 0) { unsigned long long* p = prof + blockIdx.x * 8; p[0] = t_start; p[2] = t_acc; p[3] = clk(); p[4] = g_start; p[5] = gtime(); p[6] = t_epi; }
    if (warp == 1 && lane == 0 && rank == 0) prof[blockIdx.x * 8 + 1] = t_first;
  }
  if (warp == 3) {
    asm volatile("tcgen05.fence::after_thread_sync;");
    asm volatile("tcgen05.dealloc.cta_group::2.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(kTmemCols));
  }
}
}
extern "C" int tc_pair2_run(const float* emb, const float* W, const float* bias, float* const* outs, int B, int n1, int kbs, int stages, int mode,
                            unsigned long long* prof, cudaStream_t stream) {
  if (B <= 256 || B > 512) return 420;
  const int Bpad = (B + 15) / 16 * 16;
  if (n1 <= 0) n1 = 256;
  const int n2h = (Bpad - n1) / 2;
  const int perK = kWBlk + (Bpad / 2) * 128, avail = kSmemDyn - 1024;
  if (kbs <= 0 || kKB % kbs) return 421;
  if (stages <= 0) stages = avail / (kbs * perK);
  if (stages > kMaxStages) stages = kMaxStages;
  if (stages < 2 || stages * kbs * perK > avail) return 422;
  CUtensorMap mW, mE1, mE2;
  cuuint64_t dW[3] = {(cuuint64_t)kBK, (cuuint64_t)kN, (cuuint64_t)kKB}, sW[2] = {(cuuint64_t)kD * 4, (cuuint64_t)kBK * 4};
  cuuint32_t bW[3] = {kBK, kRows, (cuuint32_t)kbs}, es[3] = {1, 1, 1};
  if (cuTensorMapEncodeTiled(&mW, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 3, (void*)W, dW, sW, bW, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
      CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) return 423;
  cuuint64_t dE[2] = {(cuuint64_t)kD, (cuuint64_t)B}, sE[1] = {(cuuint64_t)kD * 4};
  cuuint32_t bE1[2] = {kBK, (cuuint32_t)(n1 / 2)}, bE2[2] = {kBK, (cuuint32_t)n2h};
  if (cuTensorMapEncodeTiled(&mE1, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 2, (void*)emb, dE, sE, bE1, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
      CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) return 424;
  if (cuTensorMapEncodeTiled(&mE2, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 2, (void*)emb, dE, sE, bE2, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
      CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) return 425;
  static bool attr_set = false;
  if (!attr_set) { cudaFuncSetAttribute(tc_pair2_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemDyn); attr_set = true; }
  OutPtrs op; for (int i = 0; i < 6; ++i) op.p[i] = outs[i];
  cudaLaunchConfig_t cfg = {};
  cfg.gridDim = dim3(kN / kRows); cfg.blockDim = dim3(kThreads);
  cfg.dynamicSmemBytes = stages * kbs * perK + 1024; cfg.stream = stream;
  cudaLaunchAttribute at[1];
  at[0].id = cudaLaunchAttributeClusterDimension; at[0].val.clusterDim.x = 2; at[0].val.clusterDim.y = 1; at[0].val.clusterDim.z = 1;
  cfg.attrs = at; cfg.numAttrs = 1;
  cudaLaunchKernelEx(&cfg, tc_pair2_kernel, mW, mE1, mE2, bias, op, B, Bpad, n1, kbs, stages, mode, prof);
  return (int)cudaGetLastError();
}
